  ('44444444-4444-4444-8444-444444444401', 'strategy', '{"en":"Strategy","de":"Strategie","fr":"Stratégie","es":"Estrategia"}'::jsonb, '{"en":"Positioning, planning, and strategic direction for digital growth.","de":"Positionierung, Planung und strategische Ausrichtung für digitales Wachstum.","fr":"Positionnement, planification et direction stratégique pour la croissance digitale.","es":"Posicionamiento, planificación y dirección estratégica para el crecimiento digital."}'::jsonb),
  ('44444444-4444-4444-8444-444444444402', 'design-ux', '{"en":"Design & UX","de":"Design & UX","fr":"Design et UX","es":"Diseño y UX"}'::jsonb, '{"en":"Digital experiences designed around clarity, usability, and conversion.","de":"Digitale Erlebnisse, gestaltet für Klarheit, Nutzerfreundlichkeit und Conversion.","fr":"Des expériences numériques conçues autour de la clarté, de l''utilisabilité et de la conversion.","es":"Experiencias digitales diseñadas en torno a la claridad, la usabilidad y la conversión."}'::jsonb),
  ('44444444-4444-4444-8444-444444444403', 'web-development', '{"en":"Web Development","de":"Webentwicklung","fr":"Développement web","es":"Desarrollo web"}'::jsonb, '{"en":"Building fast, reliable, and scalable websites and web applications.","de":"Entwicklung schneller, zuverlässiger und skalierbarer Websites und Webanwendungen.","fr":"Création de sites et d''applications web rapides, fiables et évolutifs.","es":"Creación de sitios y aplicaciones web rápidos, fiables y escalables."}'::jsonb),
